    : this.http.get<Product[]>('/api/products', {
        params: { q }, timeout: 5_000,
      }).pipe(
        map(items => ({ kind: 'ready' as const, items })),
        startWith({ kind: 'loading' as const, items: [] }),
        catchError(error => of({ kind: 'error' as const, items: [], error })),
      )
  ),
  shareReplay({ bufferSize: 1, refCount: true }),
); `catchError` nằm **bên trong** `switchMap` để một request lỗi không giết luôn stream search. `shareReplay` tránh nhiều consumer tạo request lặp, nhưng cache có lifetime và invalidation cần chủ đích; không dùng nó như global cache vô hạn. Bridge giữa Observable và Signal Signal phù hợp cho state đồng bộ mà template đọc; Observable mạnh ở event theo thời gian, cancellation và composition. `toSignal(stream$, { initialValue })` quản lý subscription theo injection context. `toObservable(signal)` đưa state signal vào pipeline RxJS. Không gọi `toSignal` lặp lại trong getter/template vì mỗi lần có thể tạo subscription mới. Với subscription imperative, dùng `takeUntilDestroyed()` hoặc ownership tương đương. `HttpClient` thường complete sau response, nhưng stream dài như WebSocket, form changes và router events thì không. Interceptor là middleware, không phải nơi chứa mọi nghiệp vụ Functional interceptor có thứ tự cấu hình dễ đoán. Request/response phần lớn immutable; muốn thêm header phải `clone`. Interceptor có thể gắn correlation ID, auth header cho đúng origin, deadline và telemetry. Nó không nên đổi business error thành fake success. export const correlationInterceptor: HttpInterceptorFn = (request, next) => {
  if (!request.url.startsWith('/api/')) return next(request);

  const enriched = request.clone({
    setHeaders: { 'X-Correlation-Id': crypto.randomUUID() },
  });
  const started = performance.now();

  return next(enriched).pipe(finalize(() => {
    console.debug('http_completed', enriched.method, enriched.url,
      Math.round(performance.now() - started));
  }));
}; Auth interceptor phải tránh gửi credential sang CDN/third-party URL. Refresh-token flow cần single-flight để nhiều response 401 không đồng loạt refresh. Retry chỉ dành cho lỗi transient và operation idempotent hoặc có idempotency key; retry một `POST /payments` mù quáng có thể tạo giao dịch kép. Generic `http.get<User>()` chỉ type-check code TypeScript; nó không kiểm tra JSON runtime. Boundary quan trọng vẫn cần schema validation hoặc mapping rõ ràng trước khi dữ liệu vào domain/UI state. Error taxonomy và UX Network error, timeout và abort đều có thể khác với HTTP 4xx/5xx; log phải phân loại. 401 thường là authentication/session; 403 là đã xác thực nhưng thiếu quyền; không tự retry cả hai. 429/503 có thể retry theo `Retry-After`, exponential backoff và jitter nếu deadline còn đủ. Validation 400/422 cần map lỗi theo field; đừng biến thành toast chung “có lỗi”. Khi user đổi route/query, cancellation là outcome dự kiến, không phải incident. Testing contract thay vì implementation detail `provideHttpClientTesting()` thay backend thật. Test nên assert method, URL/params, header quan trọng, body, response mapping và error path; cuối test gọi `verify()` để bắt request ngoài dự kiến. Khi test interceptor, cấu hình `provideHttpClient(withInterceptors(...))` trước testing provider. const promise = firstValueFrom(api.find('router'));
const request = httpTesting.expectOne(r =>
  r.method === 'GET' && r.url === '/api/products' && r.params.get('q') === 'router');

request.flush([{ id: 'p-1', name: 'Router' }]);
