  provideClientHydration,
  withIncrementalHydration,
} from '@angular/platform-browser';

export const appConfig = {
  providers: [provideClientHydration(withIncrementalHydration())],
}; @defer (on viewport; hydrate on interaction) {
  <app-reviews [productId]="productId()" />
} @placeholder {
  <section class="reviews-skeleton" aria-label="Đánh giá sẽ được tải"></section>
} @error {
  <p role="alert">Không tải được phần đánh giá.</p>
} Ở initial SSR, hydrate trigger cho phép main content được render server nhưng chunk client trì hoãn đến interaction; event replay giữ một số event trước hydration rồi phát lại. Event replay giảm mất click, không biến mọi operation thành exactly-once: handler phải chống double submit/idempotent ở business boundary. Regular trigger (`on viewport`) chi phối client-side navigation sau initial load; hydrate trigger chỉ chi phối initial hydrated page. Nested dehydrated block cần hydrate ancestors trước. Tránh nhiều nested block cùng trigger gây cascading chunk requests. Placeholder phải ổn định kích thước, accessible và không giả nút bấm hoạt động khi subtree chưa hydrate. Đo đúng và troubleshoot Đừng kết luận SSR nhanh từ Lighthouse một lần. So cùng route/device/cache state và tách: TTFB/server render/downstream duration. HTML bytes, transfer state size, initial/deferred JS bytes. LCP/layout shift và thời điểm control thật sự interactive. Hydration duration/mismatch count, long task và event replay delay. SSR error/timeout, active render/queue, cache hit và memory per worker. Troubleshooting mismatch: lấy URL/request identity, tắt extension/third-party script, so server HTML với DOM trước hydration, tìm browser-only conditional/random/invalid markup, khoanh component nhỏ nhất. Troubleshooting duplicate API: kiểm transfer-cache eligibility, request URL/headers/body khác nhau và thời điểm app stable; không chữa bằng global `shareReplay` giữ data user cũ. Failure scenarios: SSR cache thiếu tenant/locale key: cross-user data leak; purge, disable cache và audit ngay. Downstream chậm: render queue tăng rồi OOM; deadline, concurrency/admission limit và CSR/partial fallback. Deploy HTML và chunk lệch version: hydration/chunk 404; atomic asset deploy, immutable filenames và giữ version cũ qua grace window. `hydrate never` bao subtree tương tác: UI trông sẵn nhưng không hoạt động; chỉ dùng content static và test keyboard. Analytics sửa DOM sớm: mismatch; trì hoãn sau hydration hoặc tích hợp qua safe boundary. Production checklist [ ] Mỗi route có lý do CSR/SSG/SSR, freshness, cache và fallback rõ. [ ] Server code không phụ thuộc browser global; request state không nằm trong singleton chia sẻ. [ ] HTML/server-client data deterministic; hydration mismatch bằng 0 trong critical journey. [ ] Transfer cache loại auth/cookie/PII, key đúng tenant/variant và giới hạn payload. [ ] `@defer` chunk thực sự tách; placeholder/loading/error accessible và giữ layout. [ ] Incremental hydration config khớp Angular 21 hoặc 22 đang deploy. [ ] SSR có timeout, concurrency/memory bound, tracing và rollback/degrade path. [ ] Test hard reload, client navigation, slow JS, pre-hydration interaction và mixed-version deploy. Góc phỏng vấn **SSR khác hydration thế nào?** SSR tạo HTML trên server; hydration làm HTML đó sống trên client bằng cách nối runtime/component với DOM. HTML thấy sớm không đồng nghĩa tương tác sớm. **Khi nào chọn SSG thay SSR?** Khi dữ liệu có thể biết ở build-time và freshness/invalidation chấp nhận được; đổi lại giảm request-time compute và dễ CDN cache. **@defer có luôn cải thiện performance?** Không. Nó giảm initial bundle/work nhưng thêm request và delay. Above-the-fold cần incremental hydration hoặc thiết kế khác; quyết định bằng user journey evidence. Key Takeaways Rendering mode là quyết định theo route, data freshness, SEO, server cost và interactivity. Hydration reuse DOM chỉ đúng khi server/client first render deterministic và không bị script sửa sớm. Incremental hydration tách “HTML đã thấy” khỏi “code đã tải và tương tác”; event replay không thay idempotency. Angular 21 và 22 khác cách bật incremental hydration, nên version-aware configuration là bắt buộc. Đo cả server queue/TTFB lẫn browser LCP, hydration và interaction; tối ưu một phía có thể làm phía kia xấu đi.

