@Injectable()
export class CartState {
  private readonly _lines = signal<readonly CartLine[]>([]);
  readonly lines = this._lines.asReadonly();
  readonly total = computed(() =>
    this._lines().reduce((sum, line) => sum + line.price * line.quantity, 0)
  );

  changeQuantity(id: string, quantity: number): void {
    if (!Number.isInteger(quantity) || quantity < 1) throw new Error('invalid quantity');
    this._lines.update(lines => lines.map(line =>
      line.id === id ? { ...line, quantity } : line
    ));
  }
}

searchText:
Đừng bắt đầu bằng tên library State management là bài toán ownership và transition, không phải cuộc thi Signals với NgRx. Trước khi chọn công cụ, lập inventory: **Ephemeral UI state:** menu mở, tab đang chọn, input draft; thường owner là component. **Route state:** path, query, fragment; URL nên là source of truth nếu cần bookmark/share/back-forward. **Server state:** entity/query result, freshness, error, pagination; backend vẫn là authority, client chỉ cache/projection. **Session state:** current user, tenant, permissions; lifetime vượt component nhưng phải reset đúng login/logout/tenant switch. **Workflow state:** multi-step checkout, optimistic command, websocket/event cạnh tranh; cần transition và reconciliation rõ. **Derived state:** filtered rows, total, permission view; nên tính từ source, không lưu bản sao nếu không cần. Ba câu hỏi quyết định phần lớn kiến trúc: ai được ghi, state sống bao lâu, và có bao nhiêu nguồn event bất đồng bộ cùng tác động? Một form component không cần global action/reducer. Ngược lại, workflow có router, websocket, offline resume và nhiều team cùng sửa sẽ khó audit nếu chỉ có vài `signal()` công khai trong root service. flowchart TD
  Q{Owner và lifetime?} -->|Một component/route| S[Local signal/service]
  Q -->|Temporal stream| R[RxJS composition]
  Q -->|Feature local cần conventions| SS[NgRx SignalStore]
  Q -->|Global + nhiều event/source/team| G[NgRx Global Store]
  S --> X[Escalate chỉ khi pain được đo]
  R --> X
  SS --> X Signals: state hiện tại và derived graph Signal phù hợp khi consumer cần đọc giá trị hiện tại đồng bộ và Angular cần track dependency render. Writable signal là state nhỏ; `computed` là pure derived state; method của service là command boundary. Giấu writable signal để component không bypass invariant: @Injectable()
export class CartState {
  private readonly _lines = signal<readonly CartLine[]>([]);
  readonly lines = this._lines.asReadonly();
  readonly total = computed(() =>
    this._lines().reduce((sum, line) => sum + line.price * line.quantity, 0)
  );

  changeQuantity(id: string, quantity: number): void {
    if (!Number.isInteger(quantity) || quantity < 1) throw new Error('invalid quantity');
    this._lines.update(lines => lines.map(line =>
      line.id === id ? { ...line, quantity } : line
    ));
